typedef struct DNode {
    int value;
    struct DNode* next;
    struct DNode* prev;
} DNode;

void insertAfter(DNode* target, int value) {
    DNode* n = (DNode*)malloc(sizeof(DNode));
    n->value = value;
    n->next = target->next;
    n->prev = target;
    if (target->next != NULL) {
        target->next->prev = n;
    }
    target->next = n;
}

